  double LAT0_RAD() const {
    return GetField<double>(VT_LAT0_RAD, 0.0);
  }
  /// Longitude of the first column's cell centre, radians.
  double LON0_RAD() const {
    return GetField<double>(VT_LON0_RAD, 0.0);
  }
  /// Latitude step between rows, radians (signed).
  double DLAT_RAD() const {
    return GetField<double>(VT_DLAT_RAD, 0.0);
  }
  /// Longitude step between columns, radians (signed).
  double DLON_RAD() const {
    return GetField<double>(VT_DLON_RAD, 0.0);
  }
  /// Number of rows.
  uint32_t NLAT() const {
    return GetField<uint32_t>(VT_NLAT, 0);
  }
  /// Number of columns.
  uint32_t NLON() const {
    return GetField<uint32_t>(VT_NLON, 0);
  }
  /// Low-cloud cover fraction per cell, [0, 1]. NaN marks a missing cell.
  const ::flatbuffers::Vector<float> *LOW_COVER() const {
    return GetPointer<const ::flatbuffers::Vector<float> *>(VT_LOW_COVER);
  }
  /// Medium-cloud cover fraction per cell, [0, 1]. Absent when unstated.
  const ::flatbuffers::Vector<float> *MEDIUM_COVER() const {
    return GetPointer<const ::flatbuffers::Vector<float> *>(VT_MEDIUM_COVER);
  }
  /// High-cloud cover fraction per cell, [0, 1]. Absent when unstated.
  const ::flatbuffers::Vector<float> *HIGH_COVER() const {
    return GetPointer<const ::flatbuffers::Vector<float> *>(VT_HIGH_COVER);
  }
