           VerifyField<uint32_t>(verifier, VT_NLAT, 4) &&
           VerifyField<uint32_t>(verifier, VT_NLON, 4) &&
           VerifyOffset(verifier, VT_LOW_COVER) &&
           verifier.VerifyVector(LOW_COVER()) &&
           VerifyOffset(verifier, VT_MEDIUM_COVER) &&
           verifier.VerifyVector(MEDIUM_COVER()) &&
           VerifyOffset(verifier, VT_HIGH_COVER) &&
           verifier.VerifyVector(HIGH_COVER()) &&
           VerifyOffset(verifier, VT_BASE_HEIGHT_M) &&
           verifier.VerifyVector(BASE_HEIGHT_M()) &&
           VerifyOffset(verifier, VT_TOP_HEIGHT_M) &&
           verifier.VerifyVector(TOP_HEIGHT_M()) &&
           VerifyOffset(verifier, VT_COLUMN_OPTICAL_DEPTH) &&
           verifier.VerifyVector(COLUMN_OPTICAL_DEPTH()) &&
           verifier.EndTable();
