  double SOUTH_RAD = 0.0;
  double EAST_RAD = 0.0;
  double NORTH_RAD = 0.0;
  double MIN_HEIGHT_M = 0.0;
  double MAX_HEIGHT_M = 0.0;
  double ORIGIN_LON_RAD = 0.0;
