  const ::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>> *SOURCE_FIELD_IDS() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>> *>(VT_SOURCE_FIELD_IDS);
  }
