inline const GCT *GetGCT(const void *buf) {
  return ::flatbuffers::GetRoot<GCT>(buf);
}

inline const GCT *GetSizePrefixedGCT(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<GCT>(buf);
}

inline const char *GCTIdentifier() {
  return "$GCT";
}

inline bool GCTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GCTIdentifier());
}

inline bool SizePrefixedGCTBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, GCTIdentifier(), true);
}

template <bool B = false>
inline bool VerifyGCTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<GCT>(GCTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedGCTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<GCT>(GCTIdentifier());
}

inline void FinishGCTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GCT> root) {
  fbb.Finish(root, GCTIdentifier());
}

inline void FinishSizePrefixedGCTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<GCT> root) {
  fbb.FinishSizePrefixed(root, GCTIdentifier());
}

inline std::unique_ptr<GCTT> UnPackGCT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<GCTT>(GetGCT(buf)->UnPack(res));
}

inline std::unique_ptr<GCTT> UnPackSizePrefixedGCT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<GCTT>(GetSizePrefixedGCT(buf)->UnPack(res));
}

